 // ============================================
 // EVOLUTION API PAYLOAD NORMALIZER
 // Project #4 — preserve raw message for voice retrieval
 // ============================================

const root = items[0].json || {};
const payload = root.body || root;

const event = String(payload.event || '').toLowerCase();

if (event !== 'messages.upsert') {
  return [{
    json: {
      skip: true,
      reason: 'not a message event',
      event
    }
  }];
}

const data = payload.data || {};
const key = data.key || {};

// Ignore messages sent by the bot itself
if (key.fromMe === true) {
  return [{
    json: {
      skip: true,
      reason: 'fromMe message'
    }
  }];
}

const remoteJid = key.remoteJid || '';

// Ignore group messages
if (remoteJid.includes('@g.us')) {
  return [{
    json: {
      skip: true,
      reason: 'group message'
    }
  }];
}

const phone = remoteJid.replace(
  /@s\.whatsapp\.net|@c\.us|@g\.us/g,
  ''
);

const senderName = data.pushName || 'Customer';
const messageType = data.messageType || 'conversation';
const instanceName = payload.instance || 'project4-test';

const isAudio =
  messageType === 'audioMessage' ||
  messageType === 'audio';

const isText =
  messageType === 'conversation' ||
  messageType === 'extendedTextMessage';

let text = '';

if (isText) {
  text =
    data.message?.conversation ||
    data.message?.extendedTextMessage?.text ||
    '';
}

// Base64 may be absent from the webhook.
// Preserve the complete message so the media can be retrieved separately.
const audioBase64 = isAudio
  ? (
      data.base64 ||
      data.media ||
      data.message?.base64 ||
      ''
    )
  : '';

const messageId = key.id || '';

const timestamp = data.messageTimestamp
  ? new Date(Number(data.messageTimestamp) * 1000).toISOString()
  : '';

return [{
  json: {
    skip: false,
    phone,
    sender_name: senderName,
    message_type: isAudio ? 'voice' : 'text',
    text: text || (isAudio ? '[voice message]' : ''),
    audio_base64: audioBase64,
    message_id: messageId,
    timestamp,
    instance_name: instanceName,
    raw_type: messageType,

    // Preserve source data for the media retrieval request
    message_key: key,
    raw_message: data.message || {},
    raw_data: data
  }
}];

// ============================================
// PREPARE AUDIO FOR OPENAI TRANSCRIPTION
// Project #4 — Evolution API media retrieval
// ============================================

// Original message from Detect Message Type1
const original = $('Detect Message Type1').item.json;

// Base64 response from HTTP Request
const response = items[0].json;

const base64Audio =
  response.base64 ||
  response.data?.base64 ||
  response.media ||
  response.data?.media ||
  '';

if (!base64Audio) {
  throw new Error(
    'Base64 audio not found in HTTP Request response. Check the response fields.'
  );
}

// Remove data URL prefix if present
const cleanBase64 = base64Audio.replace(
  /^data:audio\/[^;]+;base64,/,
  ''
);

// Detect MIME type when available
const mimeType =
  response.mimetype ||
  response.mimeType ||
  response.data?.mimetype ||
  response.data?.mimeType ||
  'audio/ogg';

const extension = mimeType.includes('mpeg')
  ? 'mp3'
  : mimeType.includes('mp4')
    ? 'mp4'
    : mimeType.includes('wav')
      ? 'wav'
      : 'ogg';

const buffer = Buffer.from(cleanBase64, 'base64');

return [{
  json: {
    ...original,
    audio_base64: cleanBase64,
    text: original.text || '[voice message]'
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType,
      fileName: `audio.${extension}`
    }
  }
}];

