// Strip markdown formatting from AI response
let text = $input.item.json.output || '';

// Remove bold/italic
text = text.replace(/\*\*(.*?)\*\*/g, '$1');
text = text.replace(/\*(.*?)\*/g, '$1');
text = text.replace(/_(.*?)_/g, '$1');

// Replace em dashes with comma
text = text.replace(/ — /g, ', ');
text = text.replace(/—/g, ', ');

// Remove markdown headers
text = text.replace(/^#{1,3}\s+/gm, '');

// Clean up extra blank lines (max 1)
text = text.replace(/\n{3,}/g, '\n\n');

// P5: carry a stable dedup key (the HTTP node replaces the item downstream).
// P5: preserve the key created by Dedup Check1.
const claim = $('Dedup Check1').first().json;
const key = claim.dedup_key;

if (!key || claim.dedup_status !== 'processing' || claim.is_duplicate === true) {
  throw new Error('Dedup claim missing, duplicate, or not processing; refusing to send.');
}

return { json: { ...$input.item.json, output: text.trim(), dedup_key: key } };

// ============================================
// NORMALIZE AND LOOK MATCH - Get Lead Early
// Input: Google Sheets row(s) from "Get row(s) in sheet" (sheet: Leads)
// Columns: phone, name, status, language, source,
//          intent, last_message, last_contact, bot_status, row_number
// NOTE: "Get row(s) in sheet" has alwaysOutputData=true, so when no lead
//       matches, the input arrives as a single empty object: [{}]
// ============================================

const webhookPhone = $('Detect Message Type1').first().json.phone;
const leadRows     = $input.all();

const messageData = {
  phone:         $('Detect Message Type1').first().json.phone,
  sender_name:   $('Detect Message Type1').first().json.sender_name,
  message_type:  $('Detect Message Type1').first().json.message_type,
  instance_name: $('Detect Message Type1').first().json.instance_name,
  text: $('Sentiment Analysis1').first().json.text
        || $('Detect Message Type1').first().json.text
        || ''
};

const normalize = (p) => {
  let n = String(p || '').replace(/[^0-9]/g, '');
  // Add country-specific phone normalization here if needed
  return n;
};

const normalizedWebhook = normalize(webhookPhone);

// Only compare real phone numbers. This also prevents the empty [{}] row from
// matching when both sides normalize to an empty string.
const match = normalizedWebhook.length >= 10
  ? leadRows.find(item => {
      const rowPhone = normalize(item.json.phone || '');
      return rowPhone.length >= 10 && rowPhone === normalizedWebhook;
    })
  : undefined;

if (match) {
  return [{
    json: {
      ...messageData,
      is_known_lead: true,
      matched:       true,
      page_id:       '',
      bot_status:    match.json.bot_status || 'Active',
      lead_status:   match.json.status || '',
      row_number:    match.json.row_number || null
    }
  }];
}

return [{
  json: {
    ...messageData,
    is_known_lead: false,
    matched:       false,
    page_id:       '',
    bot_status:    'Active'
  }
}];

 // ============================================================================
 // P1 - classify the REAL Evolution / Meta outcome.
 // HTTP 2xx alone is NOT acceptance:
 // 201 + body.key.id -> accepted
 // provider error fields -> failed
 // output 1 (json.error) -> failed
 // no response captured -> unknown
 // node not executed -> not_attempted
 // Delivery to the handset is NOT provable here.
 // No MESSAGES_UPDATE webhook is subscribed, so delivery_confirmed is false.
 // ============================================================================

const SEND = 'Send WhatsApp Reply (Evolution)1';
const STATUSES = ['PENDING', 'SERVER_ACK', 'DELIVERY_ACK', 'READ', 'PLAYED'];

// Fields for the log come from Format Cleaner1; HTTP replaces the item.
let src = {};
try {
  src = $('Format Cleaner1').item.json;
} catch (e) {
  try {
    src = $('Format Cleaner1').first().json;
  } catch (e2) {
    src = {};
  }
}

let delivery_state = 'unknown';
let delivery_detail = '';
let provider_message_id = null;
let accepted = false;

let executed = false;
try {
  executed = $(SEND).isExecuted === true;
} catch (e) {
  executed = false;
}

if (!executed) {
  delivery_state = 'not_attempted';
  delivery_detail = 'send node not executed (no attempt made)';
} else {
  try {
    const j = $json || {};
    const err = j.error;
    const code = Number(j.statusCode || 0);
    const rawBody = j.body;

    const body =
      rawBody &&
      typeof rawBody === 'object' &&
      !Array.isArray(rawBody)
        ? rawBody
        : null;

    const hasKey = !!(
      body &&
      body.key &&
      typeof body.key.id === 'string' &&
      body.key.id.length > 0
    );

    // Do not treat body.message as an error:
    // Evolution uses it to return the sent message content.
    const providerErr = !!(
      body &&
      (body.error_data || body.error)
    );

    if (err !== undefined && err !== null) {
      delivery_state = 'failed';

      const m =
        (err &&
          (err.message || (err.error && err.error.message))) ||
        String(err);

      delivery_detail =
        'http ' + (code || 'n/a') + ': ' + String(m).slice(0, 300);

    } else if (code === 0 && !hasKey && !providerErr) {
      delivery_state = 'unknown';
      delivery_detail = 'no HTTP response captured (timeout/reset)';

    } else if (providerErr) {
      delivery_state = 'failed';

      const providerError =
        body.error_data || body.error;

      const errorText =
        typeof providerError === 'string'
          ? providerError
          : JSON.stringify(providerError);

      delivery_detail =
        'provider error inside HTTP ' +
        code +
        ': ' +
        String(errorText || '').slice(0, 300);

    } else if (hasKey) {
      accepted = true;
      delivery_state = 'accepted';
      provider_message_id = body.key.id;

      const st = String(body.status || '');

      delivery_detail =
        STATUSES.indexOf(st) >= 0
          ? 'provider accepted; provider status=' + st
          : 'provider accepted; unrecognised provider status=' +
            (st || '(none)');

    } else {
      delivery_state = 'unknown';
      delivery_detail = 'http ' + code + ' with unrecognised body';
    }
  } catch (e) {
    delivery_state = 'unknown';
    delivery_detail =
      'classification error: ' + String((e && e.message) || e);
  }
}

const out = Object.assign({}, src, {
  delivery_state: delivery_state,
  delivery_detail: delivery_detail,
  send_accepted: accepted,
  delivery_confirmed: false,
  provider_message_id: provider_message_id,
});

return { json: out };

// P5 - atomic inbound deduplication.
// A real SQLite table with message_id PRIMARY KEY on the persistent n8n volume.
// The uniqueness check and the row write are ONE indivisible operation, so two
// concurrent executions can never both claim the same message id.
// $getWorkflowStaticData is deliberately NOT used: it is a read-at-start /
// write-at-end whole-object snapshot and was measured to double-claim 10/10.
// ============================================================================
const { DatabaseSync } = require('node:sqlite');

const DB_PATH = '/home/node/.n8n/project04_dedup.sqlite';
const TTL_MS = 15 * 60 * 1000;

const db = new DatabaseSync(DB_PATH);
// busy_timeout FIRST: without it a concurrent opener fails at the WAL switch with
// "database is locked" before any retry budget exists.
db.exec('PRAGMA busy_timeout=10000');
try { db.exec('PRAGMA journal_mode=WAL'); } catch (e) { /* best effort; correctness does not depend on it */ }
db.exec('CREATE TABLE IF NOT EXISTS dedup (' +
  'message_id TEXT PRIMARY KEY, status TEXT NOT NULL, ts INTEGER NOT NULL)');

const now = Date.now();
const out = [];
try {
  for (const item of $input.all()) {
    const j = item.json || {};

    // Events the workflow already skips are never claimed.
    if (j.skip === true) {
      out.push({ json: Object.assign({}, j, { dedup_status: 'skipped', is_duplicate: false }) });
      continue;
    }

    // Stable id from the inbound payload. Date.now() is NEVER used as an id.
    let key = (j.message_id && String(j.message_id).trim()) ? String(j.message_id).trim() : null;

    if (!key) {
      // Fail closed when the provider did not supply a stable message id.
      // Voice payloads have no stable text fingerprint here; never derive a key
      // from timestamp alone or treat two distinct audio messages as duplicates.
      // Text may use a deterministic surrogate only when provider timestamp and
      // non-empty text are both present. Otherwise stop before AI/send nodes.
      if (j.message_type === 'voice') {
        out.push({ json: Object.assign({}, j, { dedup_status: 'unverifiable', is_duplicate: false }) });
        continue;
      }
      if (j.timestamp && String(j.text || '').trim()) {
        const tuple = [j.instance_name || '', j.phone || '', j.raw_type || '',
                       String(j.timestamp), String(j.text).slice(0, 400)];
        key = 'derived:' + JSON.stringify(tuple);
      } else {
        // No trustworthy key: no claim, no guarantee, and no auto-send.
        out.push({ json: Object.assign({}, j, { dedup_status: 'unverifiable', is_duplicate: false }) });
        continue;
      }
    }

    let claimed = false;
    // Bounded retry: under a webhook burst a writer can still meet SQLITE_BUSY momentarily.
    // Retrying the same atomic claim is safe - the PRIMARY KEY decides, so a retry can only
    // ever turn a failure into a correct answer, never into a double-claim.
    let attempt = 0;
    for (;;) {
      try {
        db.exec('BEGIN IMMEDIATE');
        try {
          // TTL policy: terminal outcomes accepted/failed are retained for 15 minutes,
          // then eligible for a fresh claim. 'unknown' is deliberately NOT auto-expired:
          // the provider may have accepted a send even when n8n lost the response, so
          // retrying that inbound event could send a duplicate to the customer.
          db.prepare(            "DELETE FROM dedup WHERE status IN ('accepted', 'failed') AND ts < ?"
          ).run(now - TTL_MS);

          const row = db.prepare('SELECT status, ts FROM dedup WHERE message_id = ?').get(key);
          if (row) {
            // A crashed/slow attempt with no terminal result is made unknown and remains
            // blocked. This is fail-closed: expiry alone cannot prove no reply was sent.
            if (row.status === 'processing' && (now - row.ts) > TTL_MS) {
              db.prepare('UPDATE dedup SET status = ?, ts = ? WHERE message_id = ?')
                .run('unknown', now, key);
            }
            claimed = false;
          } else {
            db.prepare('INSERT INTO dedup (message_id, status, ts) VALUES (?, ?, ?)')
              .run(key, 'processing', now);
            claimed = true;
          }
          db.exec('COMMIT');
        } catch (e) {
          try { db.exec('ROLLBACK'); } catch (e2) { /* already rolled back */ }
          throw e;
        }
        break;
      } catch (e) {
        const msg = String((e && e.message) || e);
        if (/locked|busy/i.test(msg) && attempt < 8) {
          attempt++;
          // small blocking pause; no timers, so the sandbox cannot be left with pending handles
          const until = Date.now() + (20 * attempt);
          while (Date.now() < until) { /* spin briefly */ }
          continue;
        }
        throw e;
      }
    }

    out.push({
      json: Object.assign({}, j, {
        dedup_key: key,
        is_duplicate: !claimed,
        dedup_status: claimed ? 'processing' : 'duplicate',
      }),
    });
  }
} finally {
  db.close();
}
return out;

// ============================================================================
// P5 - record the terminal delivery state for this message id.
const { DatabaseSync } = require('node:sqlite');

const db = new DatabaseSync('/home/node/.n8n/project04_dedup.sqlite');
db.exec('PRAGMA busy_timeout=10000');

const j = $json || {};
const key = j.dedup_key;
let dedup_recorded = 'n/a';

try {
  if (key) {
    const st = j.delivery_state;
    const terminal =
      st === 'accepted' ? 'accepted' :
      st === 'failed' ? 'failed' :
      'unknown';

    const result = db.prepare(
      'UPDATE dedup SET status = ?, ts = ? WHERE message_id = ?'
    ).run(terminal, Date.now(), key);

    dedup_recorded =
      Number(result.changes) === 1
        ? terminal
        : 'write_failed_no_matching_row';
  }
} finally {
  db.close();
}

return {
  json: Object.assign({}, j, {
    dedup_recorded: dedup_recorded
  })
};

