const original = $('Prepare Audio Binary1').item.json;
const response = $input.item.json;

const transcript = response.text;

if (typeof transcript !== 'string' || !transcript.trim()) {
  throw new Error(
    'Whisper did not return a non-empty transcription in response.text'
  );
}

return {
  json: {
    ...original,
    text: transcript,
    transcription: transcript,
  },
};
